CREATE TABLE [dbo].[ReportsFilters](	  [reportName] NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [filterName] NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [id] INT NOT NULL	, CONSTRAINT [PK_ReportsFilters] PRIMARY KEY ([reportName] ASC, [filterName] ASC, [id] ASC))ALTER TABLE [dbo].[ReportsFilters] WITH CHECK ADD CONSTRAINT [FK_ReportsFilters_FilterName] FOREIGN KEY([filterName]) REFERENCES [dbo].[Filters] ([name]) ON DELETE CASCADE ON UPDATE CASCADEALTER TABLE [dbo].[ReportsFilters] CHECK CONSTRAINT [FK_ReportsFilters_FilterName]